-- Daily site work (CM-601, ADR CM-0016 §1, §6): the Work Types master
-- with assigned Materials, and a skill on Labour Categories for the
-- worksheet's labour prefill. Touches construction_masters only (ADR-0030).
-- Seeds: every Company gets the "RCC" Work Type under its RCC department
-- (`modules/02` "Seed data"; keep in step with
-- apps/construction-management/src/masters/infrastructure/seeds/masters.json),
-- and the seed categories Helper, Labour and Unskilled become unskilled.
--
-- Generated by `prisma migrate diff`, then the CHECK, the partial unique
-- index and the data backfill Prisma cannot express.

-- CreateEnum
CREATE TYPE "construction_masters"."labour_skill" AS ENUM ('skilled', 'unskilled');

-- AlterTable
ALTER TABLE "construction_masters"."labour_categories" ADD COLUMN     "skill" "construction_masters"."labour_skill" NOT NULL DEFAULT 'skilled';

-- CreateTable
CREATE TABLE "construction_masters"."work_types" (
    "id" UUID NOT NULL,
    "workspace_id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "department_id" UUID NOT NULL,
    "is_seed" BOOLEAN NOT NULL DEFAULT false,
    "disabled_at" TIMESTAMPTZ(3),
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "created_by" TEXT NOT NULL,
    "updated_by" TEXT NOT NULL,
    "deleted_at" TIMESTAMPTZ(3),
    "deleted_by" TEXT,

    CONSTRAINT "work_types_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "construction_masters"."work_type_materials" (
    "work_type_id" UUID NOT NULL,
    "material_id" UUID NOT NULL,

    CONSTRAINT "work_type_materials_pkey" PRIMARY KEY ("work_type_id","material_id")
);

-- CreateIndex
CREATE INDEX "work_types_workspace_id_idx" ON "construction_masters"."work_types"("workspace_id");

-- CreateIndex
CREATE INDEX "work_types_department_id_idx" ON "construction_masters"."work_types"("department_id");

-- CreateIndex
CREATE INDEX "work_type_materials_material_id_idx" ON "construction_masters"."work_type_materials"("material_id");

-- AddForeignKey
ALTER TABLE "construction_masters"."work_types" ADD CONSTRAINT "work_types_department_id_fkey" FOREIGN KEY ("department_id") REFERENCES "construction_masters"."departments"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "construction_masters"."work_type_materials" ADD CONSTRAINT "work_type_materials_work_type_id_fkey" FOREIGN KEY ("work_type_id") REFERENCES "construction_masters"."work_types"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "construction_masters"."work_type_materials" ADD CONSTRAINT "work_type_materials_material_id_fkey" FOREIGN KEY ("material_id") REFERENCES "construction_masters"."materials"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- A Work Type's name is unique among the Company's live Work Types (any case).
CREATE UNIQUE INDEX "work_types_live_name_key" ON "construction_masters"."work_types"("workspace_id", lower("name")) WHERE "deleted_at" IS NULL;

ALTER TABLE "construction_masters"."work_types" ADD CONSTRAINT "work_types_name_check" CHECK (length(btrim("name")) BETWEEN 1 AND 120);

-- Backfill: the unskilled seed categories (CM-0016 §6). A Company's own
-- categories stay skilled until someone edits them.
UPDATE "construction_masters"."labour_categories"
SET "skill" = 'unskilled'
WHERE "is_seed" AND lower("name") IN ('helper', 'labour', 'unskilled');

-- Seed: "RCC" under each Company's live RCC department, unless the Company
-- already has a live Work Type of that name. Idempotent.
INSERT INTO "construction_masters"."work_types" ("id", "workspace_id", "name", "department_id", "is_seed", "created_by", "updated_by")
SELECT gen_random_uuid(), d."workspace_id", 'RCC', d."id", true, 'system', 'system'
FROM "construction_masters"."departments" d
WHERE lower(d."name") = 'rcc'
  AND d."deleted_at" IS NULL
  AND NOT EXISTS (
    SELECT 1 FROM "construction_masters"."work_types" w
    WHERE w."workspace_id" = d."workspace_id" AND lower(w."name") = 'rcc' AND w."deleted_at" IS NULL
  )
  AND d."id" = (
    SELECT d2."id" FROM "construction_masters"."departments" d2
    WHERE d2."workspace_id" = d."workspace_id" AND lower(d2."name") = 'rcc' AND d2."deleted_at" IS NULL
    ORDER BY d2."is_seed" DESC, d2."created_at" LIMIT 1
  );
